"""Client that posts records to the ingestion API."""
import json
import os
import sys
from urllib.error import HTTPError, URLError
import urllib.request

# The API address is deployment-specific, so it is supplied when the client is
# run rather than being checked into the client source.
ENDPOINT = os.environ.get("INGESTION_ENDPOINT", "")


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    """Post every record and return the number accepted by the API."""
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        # HTTPError is raised for non-2xx responses.  Do not let one rejected
        # record keep later records from being sent.
        except (HTTPError, URLError, TimeoutError) as exc:
            print(f"record {record.get('id', '<unknown>')} was not accepted: {exc}", file=sys.stderr)
    return accepted


def main():
    # Read the environment here too, so callers that set it after importing
    # this module (for example, a process supervisor) are supported.
    endpoint = os.environ.get("INGESTION_ENDPOINT", ENDPOINT)
    if not endpoint:
        raise SystemExit("INGESTION_ENDPOINT must be set to the ingestion API URL")

    records = load_records()
    accepted = post_records(endpoint, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
